changeSet.sql:
DO $do$
DECLARE
    root_id BIGINT;
    home_id BIGINT;
    base_meta TEXT;
    target_role_code TEXT;
BEGIN
    SELECT id INTO root_id
    FROM portal_menu
    WHERE deleted = false
      AND parent_id IS NULL
      AND (
        name = 'sys.nav.portal.workbench'
        OR path = 'workbench'
        OR metadata ILIKE '%"sectionKey":"workbench"%'
      )
    LIMIT 1;

    IF root_id IS NULL THEN
        RETURN;
    END IF;

    SELECT id INTO home_id
    FROM portal_menu
    WHERE parent_id = root_id
      AND (
        name = 'sys.nav.portal.workbenchHome'
        OR path = 'home'
        OR metadata ILIKE '%"entryKey":"home"%'
      )
    LIMIT 1;

    IF home_id IS NULL THEN
        base_meta := '{"sectionKey":"workbench","entryKey":"home","titleKey":"sys.nav.portal.workbenchHome","title":"首页","externalLink":"/dashboard/workbench"}';
        INSERT INTO portal_menu (
            name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted,
            created_by, created_date, last_modified_by, last_modified_date
        ) VALUES (
            'sys.nav.portal.workbenchHome', 'home', NULL, 10, base_meta, root_id, 'solar:home-2-bold-duotone', 'GENERAL', FALSE,
            'system', now(), 'system', now()
        )
        RETURNING id INTO home_id;
    END IF;

    FOR target_role_code IN
        SELECT unnest(ARRAY[
            'ROLE_EMPLOYEE',
            'ROLE_DEPT_DATA_VIEWER','ROLE_DEPT_DATA_DEV','ROLE_DEPT_DATA_OWNER','ROLE_DEPT_LEADER',
            'ROLE_INST_DATA_VIEWER','ROLE_INST_DATA_DEV','ROLE_INST_DATA_OWNER','ROLE_INST_LEADER',
            'ROLE_ADMIN','ROLE_OP_ADMIN'
        ])
    LOOP
        INSERT INTO portal_menu_visibility (
            id, menu_id, role_code, permission_code, data_level,
            created_by, created_date, last_modified_by, last_modified_date
        )
        SELECT
            nextval('portal_menu_visibility_seq'), home_id, target_role_code, NULL, 'INTERNAL',
            'system', now(), 'system', now()
        WHERE NOT EXISTS (
            SELECT 1 FROM portal_menu_visibility v
            WHERE v.menu_id = home_id AND upper(v.role_code) = upper(target_role_code)
        );
    END LOOP;
END;
$do$;
